const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Snap Count</title>\n<meta name=\"theme-color\" content=\"#14202b\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"apple-touch-icon\" href=\"/icon-192.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Source+Sans+3:wght@400;600;700&display=swap\">\n<style>\n/* Layout: one narrow column, sticky team bar, cards only for leagues and matchups */\n:root{\n  --bg:#f3f4f1; --surface:#ffffff; --ink:#14202b; --muted:#5d6872; --line:#dde1dc;\n  --accent:#d99a00; --accent-ink:#14202b; --field:#2f6b4f;\n  --ok:#2f6b4f; --warn:#b87400; --bad:#b3261e;\n  --display:\"Barlow Condensed\",\"Arial Narrow\",Arial,sans-serif;\n  --body:\"Source Sans 3\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  color-scheme:light;\n}\n@media (prefers-color-scheme:dark){:root{\n  --bg:#10181f; --surface:#18232d; --ink:#e9ece8; --muted:#97a3ad; --line:#2a3743;\n  --accent:#f0b429; --accent-ink:#10181f; --field:#5fb28a;\n  --ok:#5fb28a; --warn:#f0b429; --bad:#ff7a6e; color-scheme:dark}}\n*{box-sizing:border-box}\nhtml,body{margin:0}\nbody{background:var(--bg);color:var(--ink);font:16px/1.45 var(--body);\n  padding:env(safe-area-inset-top,0px) max(16px,env(safe-area-inset-right,0px)) calc(24px + env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px));}\n[hidden]{display:none!important}\n.wrap{max-width:640px;margin:0 auto}\nheader.top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0 10px;border-bottom:3px solid var(--ink)}\n.brand{font:700 30px/1 var(--display);letter-spacing:.02em;text-transform:uppercase;margin:0;display:flex;align-items:baseline;gap:8px}\n.brand span{background:var(--accent);color:var(--accent-ink);padding:0 6px;border-radius:2px}\n.wk{white-space:nowrap;font:600 15px/1 var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\nbutton{font:inherit;color:inherit;cursor:pointer}\nbutton:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.btn{background:var(--ink);color:var(--bg);border:0;border-radius:6px;padding:10px 14px;font-weight:700}\n.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--line)}\n.icon{background:none;border:1px solid var(--line);border-radius:6px;padding:6px 10px;font-weight:600;font-size:14px}\nnav.tabs{display:flex;gap:4px;margin:14px 0 6px;overflow-x:auto}\nnav.tabs button{border:0;background:none;padding:8px 7px;font:600 15px/1 var(--display);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);border-bottom:3px solid transparent;white-space:nowrap}\nnav.tabs button[aria-selected=true]{color:var(--ink);border-color:var(--accent)}\nh2{font:700 22px/1.1 var(--display);text-transform:uppercase;letter-spacing:.03em;margin:22px 0 10px;text-wrap:balance}\nh3{font:600 15px/1 var(--display);text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:18px 0 6px}\n.stack{display:flex;flex-direction:column;gap:10px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:14px}\n.league{display:flex;flex-direction:column;gap:8px;text-align:left;width:100%}\n.league .row1{display:flex;justify-content:space-between;align-items:center;gap:10px}\n.league .name{font:700 20px/1.1 var(--display);text-transform:uppercase;min-width:0;overflow-wrap:anywhere}\n.badge{font:600 12px/1 var(--display);letter-spacing:.1em;text-transform:uppercase;padding:4px 6px;border-radius:3px;border:1px solid var(--line);color:var(--muted);white-space:nowrap}\n.score{display:grid;grid-template-columns:1fr auto;gap:2px 12px;font-variant-numeric:tabular-nums}\n.score .t{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.score .p{font:700 22px/1.1 var(--display);text-align:right}\n.score .me{font-weight:700}\n.lead{color:var(--ok)}\n.muted{color:var(--muted)}\n.small{font-size:14px}\n.plist{list-style:none;margin:0;padding:0;background:var(--surface);border:1px solid var(--line);border-radius:8px}\n.plist li{border-top:1px solid var(--line)}\n.plist li:first-child{border-top:0}\n.prow{display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:10px;width:100%;background:none;border:0;text-align:left;padding:10px 12px}\n.pos{font:700 15px/1 var(--display);letter-spacing:.06em;text-align:center;padding:5px 0;border-radius:4px;background:var(--bg);border:1px solid var(--line)}\n.pname{min-width:0}\n.pname b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pname small{color:var(--muted);font-size:13px}\n.pts{font:700 19px/1 var(--display);font-variant-numeric:tabular-nums;text-align:right}\n.inj{display:inline-block;font:700 12px/1 var(--display);letter-spacing:.06em;padding:3px 5px;border-radius:3px;margin-left:6px;vertical-align:1px;color:#14202b;background:var(--warn)}\n.inj.bad{background:var(--bad);color:#fff}\n.inj.ok{background:var(--ok)}\nform.add{display:flex;flex-direction:column;gap:10px}\nlabel{font-weight:600;font-size:14px}\ninput,select{font:inherit;width:100%;padding:10px 12px;border-radius:6px;border:1px solid var(--line);background:var(--surface);color:var(--ink)}\n.seg{display:flex;gap:6px}\n.seg button{flex:1;padding:9px;border:1px solid var(--line);border-radius:6px;background:var(--surface);font-weight:700}\n.seg button[aria-pressed=true]{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n.acct{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 0;border-top:1px solid var(--line)}\n.acct:first-child{border-top:0}\n.err{border-left:4px solid var(--bad);background:var(--surface);padding:10px 12px;border-radius:4px;font-size:14px}\n.news a{color:var(--ink);text-decoration:none;display:block;padding:12px;border-top:1px solid var(--line)}\n.news a:first-child{border-top:0}\n.news a b{display:block;line-height:1.3}\n.news a small{color:var(--muted)}\n.news a:hover b{text-decoration:underline}\n.mine{background:color-mix(in srgb,var(--accent) 18%,transparent);border-radius:3px;padding:0 3px}\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}\n.chip{font-size:13px;padding:2px 8px;border-radius:999px;border:1px solid var(--line);color:var(--muted)}\n.chip.free{border-color:var(--ok);color:var(--ok);font-weight:600}\n.sheet{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;justify-content:center;z-index:20}\n.sheet .panel{background:var(--bg);width:100%;max-width:640px;max-height:85vh;overflow:auto;border-radius:14px 14px 0 0;padding:16px max(16px,env(safe-area-inset-right,0px)) calc(20px + env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px))}\n.back{background:none;border:0;padding:6px 0;font:600 16px/1 var(--display);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.spin{color:var(--muted);padding:18px 0;font-style:italic}\n.toggle{display:flex;align-items:center;gap:8px;font-size:14px;margin:6px 0 10px}\n.toggle input{width:auto}\n.seg.sub{margin-top:4px}\n.posf{margin:12px 0 0}\n.chip{background:none;font:inherit;font-size:13px}\nbutton.chip{cursor:pointer;padding:5px 11px;font-weight:600}\n.chip.on{background:var(--ink);color:var(--bg);border-color:var(--ink)}\n.live{color:#fff;background:var(--bad);font:700 11px/1 var(--display);letter-spacing:.08em;padding:2px 4px;border-radius:3px}\n.avg{display:flex;flex-direction:column;align-items:flex-end;font:600 16px/1 var(--display);color:var(--muted)}\n.avg small{font:600 10px/1.2 var(--display);letter-spacing:.08em;text-transform:uppercase}\n.statrow{display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:8px;margin-top:14px}\n.statrow div{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:8px 10px}\n.statrow small{display:block;color:var(--muted);font-size:12px}\n.statrow b{font:700 22px/1.1 var(--display);font-variant-numeric:tabular-nums}\n.hright{display:flex;align-items:center;gap:10px}\n.bell{background:none;border:1px solid var(--line);border-radius:8px;width:40px;height:40px;display:flex;align-items:center;justify-content:center;color:var(--ink)}\n.bell[aria-pressed=true]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}\n.ticks{margin:0 0 12px;padding-left:20px;display:flex;flex-direction:column;gap:6px;font-size:15px}\n.alstat{display:flex;align-items:center;gap:8px}\n.alstat .dot{width:10px;height:10px;border-radius:50%;background:var(--ok);flex:none}\n.stackc{display:flex;flex-direction:column;gap:2px}\n.btnrow{display:flex;gap:8px;margin-top:12px}\n.btnrow .btn{flex:1}\n.alitem{display:flex;flex-direction:column;gap:2px;padding:12px;border-top:1px solid var(--line)}\n.alitem:first-child{border-top:0}\n.alitem span{font-size:14px}\n.alitem small{color:var(--muted);font-size:12px}\n.install{display:flex;align-items:center;gap:12px;margin-top:14px;border-color:var(--accent)}\n.install img{width:44px;height:44px;border-radius:10px;flex:none}\n.install div{flex:1;min-width:0}\n.install b{display:block}\n.install span{font-size:14px;color:var(--muted)}\nfooter{margin-top:28px;color:var(--muted);font-size:13px;border-top:1px solid var(--line);padding-top:12px}\n@media (prefers-reduced-motion:no-preference){.sheet .panel{animation:up .18s ease-out}@keyframes up{from{transform:translateY(24px);opacity:.6}}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"top\">\n    <h1 class=\"brand\">Snap <span>Count</span></h1>\n    <div class=\"hright\"><div class=\"wk\" id=\"wk\"></div><button class=\"bell\" id=\"bellBtn\" aria-label=\"Alerts\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\"><path d=\"M6 17V11a6 6 0 0 1 12 0v6l1.5 2h-15L6 17Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M10 21h4\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div>\n  </header>\n  <nav class=\"tabs\" role=\"tablist\" id=\"tabs\">\n    <button role=\"tab\" data-tab=\"leagues\" aria-selected=\"true\">My Leagues</button>\n    <button role=\"tab\" data-tab=\"news\" aria-selected=\"false\">Headlines</button>\n    <button role=\"tab\" data-tab=\"trending\" aria-selected=\"false\">Trending</button>\n    <button role=\"tab\" data-tab=\"accounts\" aria-selected=\"false\">Accounts</button>\n  </nav>\n  <main id=\"view\"></main>\n  <footer>Live data from Sleeper and Fleaflicker. Headlines from ESPN and Google News, linked to the original articles.</footer>\n</div>\n<div id=\"sheet\" class=\"sheet\" hidden><div class=\"panel\" id=\"sheetPanel\" role=\"dialog\" aria-modal=\"true\"></div></div>\n\n<script>\n\"use strict\";\nconst $ = s => document.querySelector(s);\nconst esc = s => String(s == null ? \"\" : s).replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst fmt = n => (n == null || isNaN(n)) ? \"–\" : Number(n).toFixed(2);\nconst norm = s => String(s || \"\").toLowerCase().replace(/\\b(jr|sr|ii|iii|iv|v)\\b/g, \"\").replace(/[^a-z]/g, \"\");\n\n/* ---------- storage ---------- */\nconst KEY = \"snapcount.v1\";\nfunction loadAccts(){ try { return JSON.parse(localStorage.getItem(KEY)) || {sleeper:[], flea:[]}; } catch(e){ return {sleeper:[], flea:[]}; } }\nfunction saveAccts(a){ try { localStorage.setItem(KEY, JSON.stringify(a)); } catch(e){} }\nlet accts = loadAccts();\n\n/* ---------- api ---------- */\nasync function api(path){\n  const r = await fetch(path);\n  if (!r.ok) { let t = \"\"; try { t = (await r.json()).error; } catch(e){} throw new Error(t || (\"Request failed (\" + r.status + \")\")); }\n  return r.json();\n}\nlet nflState = null, players = null, playersP = null;\nasync function getState(){ if (!nflState) nflState = await api(\"/api/sleeper/state/nfl\"); return nflState; }\nfunction getPlayers(){ if (!playersP) playersP = api(\"/api/players\").then(p => (players = p)); return playersP; }\n\n/* ---------- injury ---------- */\nfunction injChip(code){\n  if (!code) return \"\";\n  const c = String(code).toUpperCase();\n  const map = {QUESTIONABLE:\"Q\", DOUBTFUL:\"D\", OUT:\"O\", \"INJURED RESERVE\":\"IR\", SUSPENDED:\"SUS\", SUS:\"SUS\", PUP:\"PUP\", NA:\"NA\", COV:\"COV\"};\n  const s = map[c] || c.slice(0,3);\n  const cls = (s === \"Q\" || s === \"P\") ? \"\" : \"bad\";\n  return '<span class=\"inj ' + cls + '\" title=\"' + esc(code) + '\">' + esc(s) + \"</span>\";\n}\n\n/* ---------- Sleeper ---------- */\nasync function sleeperLeagues(username){\n  const [st, user] = await Promise.all([getState(), api(\"/api/sleeper/user/\" + encodeURIComponent(username))]);\n  if (!user || !user.user_id) throw new Error('No Sleeper user named \"' + username + '\"');\n  const season = st.league_season || st.season;\n  const lgs = await api(\"/api/sleeper/user/\" + user.user_id + \"/leagues/nfl/\" + season) || [];\n  return lgs.map(l => ({platform:\"sleeper\", id:l.league_id, name:l.name, season, uid:user.user_id, acct:username}));\n}\nasync function sleeperDetail(L){\n  const st = await getState();\n  const week = Math.max(1, st.display_week || st.week || 1);\n  const [users, rosters, mus, lg] = await Promise.all([\n    api(\"/api/sleeper/league/\" + L.id + \"/users\"),\n    api(\"/api/sleeper/league/\" + L.id + \"/rosters\"),\n    api(\"/api/sleeper/league/\" + L.id + \"/matchups/\" + week).catch(() => []),\n    api(\"/api/sleeper/league/\" + L.id).catch(() => ({}))\n  ]);\n  await Promise.all([getPlayers(), getSeasonStats(L.season)]);\n  const rec = ((lg && lg.scoring_settings) || {}).rec;\n  const scoring = rec >= 1 ? \"ppr\" : rec >= 0.5 ? \"half\" : rec === 0 ? \"std\" : \"ppr\";\n  const uById = {}; (users || []).forEach(u => uById[u.user_id] = u);\n  const ptsByRoster = {}; (mus || []).forEach(m => ptsByRoster[m.roster_id] = m);\n  const teams = (rosters || []).map(r => {\n    const u = uById[r.owner_id] || {};\n    const s = r.settings || {};\n    const m = ptsByRoster[r.roster_id] || {};\n    const starters = new Set((r.starters || []).filter(x => x && x !== \"0\"));\n    const reserve = new Set(r.reserve || []);\n    const pp = m.players_points || {};\n    const roster = (r.players || []).map(pid => {\n      const p = players[pid] || [pid, \"\", \"\", null, null];\n      return {id:pid, name:p[0], pos:p[1] || (/^[A-Z]{2,3}$/.test(pid) ? \"DEF\" : \"\"), team:p[2], inj:p[3], injPart:p[4],\n        slot: starters.has(pid) ? \"start\" : reserve.has(pid) ? \"ir\" : \"bench\", pts: pp[pid]};\n    });\n    return {id:String(r.roster_id), name:(u.metadata && u.metadata.team_name) || u.display_name || (\"Team \" + r.roster_id),\n      owner:u.display_name || \"\", w:s.wins||0, l:s.losses||0, t:s.ties||0,\n      pf:(s.fpts||0) + (s.fpts_decimal||0)/100, roster, mine: r.owner_id === L.uid || (r.co_owners||[]).includes(L.uid),\n      matchup:m.matchup_id, wk:m.points};\n  });\n  const groups = {}; teams.forEach(t => { if (t.matchup) (groups[t.matchup] = groups[t.matchup] || []).push(t); });\n  const games = Object.values(groups).filter(g => g.length === 2).map(g => ({a:{id:g[0].id, pts:g[0].wk}, b:{id:g[1].id, pts:g[1].wk}}));\n  return {week, teams, games, starterSplit:true, scoring};\n}\n\n/* ---------- Fleaflicker ---------- */\nconst fq = (ep, params) => \"/api/flea/\" + ep + \"?\" + new URLSearchParams(Object.assign({sport:\"NFL\"}, params)).toString();\nasync function fleaLeagues(acct){\n  if (acct.type === \"league\") {\n    const st = await api(fq(\"FetchLeagueStandings\", {league_id:acct.value}));\n    const name = (st.league && st.league.name) || (\"Fleaflicker league \" + acct.value);\n    return [{platform:\"flea\", id:String(acct.value), name, myTeam:acct.team || fleaTeamFor(acct.value), acct:acct.value, acctObj:acct}];\n  }\n  const r = await api(fq(\"FetchUserLeagues\", {email:acct.value}));\n  const lgs = r.leagues || [];\n  if (!lgs.length) throw new Error(\"No Fleaflicker leagues found for \" + acct.value);\n  return lgs.map(l => ({platform:\"flea\", id:String(l.id), name:l.name, myTeam: l.ownedTeam ? String(l.ownedTeam.id) : fleaTeamFor(String(l.id)), acct:acct.value}));\n}\nconst val = x => (x && typeof x === \"object\") ? (x.value != null ? Number(x.value) : null) : (x == null ? null : Number(x));\nasync function fleaDetail(L){\n  const [stand, board, ros] = await Promise.all([\n    api(fq(\"FetchLeagueStandings\", {league_id:L.id})),\n    api(fq(\"FetchLeagueScoreboard\", {league_id:L.id})),\n    api(fq(\"FetchLeagueRosters\", {league_id:L.id}))\n  ]);\n  const week = (board.schedulePeriod && (board.schedulePeriod.ordinal || board.schedulePeriod.value)) || null;\n  const tinfo = {};\n  (stand.divisions || []).forEach(d => (d.teams || []).forEach(t => {\n    const rec = t.recordOverall || {};\n    tinfo[t.id] = {name:t.name, owner:((t.owners||[])[0]||{}).displayName || \"\", w:rec.wins||0, l:rec.losses||0, t:rec.ties||0, pf:val(t.pointsFor)};\n  }));\n  const teams = (ros.rosters || []).map(r => {\n    const t = r.team || {}; const i = tinfo[t.id] || {};\n    const roster = (r.players || []).map(lp => {\n      const p = lp.proPlayer || {}; const inj = p.injury || null;\n      return {id:String(p.id), name:p.nameFull, pos:p.position, team:p.proTeamAbbreviation,\n        inj: inj ? (inj.typeAbbreviaition || inj.typeAbbreviation || inj.typeFull) : null,\n        injPart: inj ? (inj.description || inj.typeFull) : null, slot:\"bench\", pts:null};\n    });\n    return {id:String(t.id), name:t.name || i.name, owner:i.owner || (((t.owners||[])[0]||{}).displayName) || \"\",\n      w:i.w||0, l:i.l||0, t:i.t||0, pf:i.pf, roster, mine: L.myTeam ? String(t.id) === L.myTeam : false};\n  });\n  Object.keys(tinfo).forEach(id => { if (!teams.find(t => t.id === String(id))) teams.push(Object.assign({id:String(id), roster:[], mine: L.myTeam === String(id)}, tinfo[id])); });\n  const games = (board.games || []).map(g => {\n    const hs = g.homeScore && g.homeScore.score, as = g.awayScore && g.awayScore.score;\n    return {a:{id:String((g.away||{}).id), pts: as ? val(as) : val((g.away||{}).pointsFor)},\n            b:{id:String((g.home||{}).id), pts: hs ? val(hs) : val((g.home||{}).pointsFor)},\n            live: !!g.isInProgress, final: !!g.isFinalScore};\n  }).filter(g => g.a.id !== \"undefined\" && g.b.id !== \"undefined\");\n  return {week, teams, games, starterSplit:false};\n}\n\n/* ---------- league cache ---------- */\nlet leagues = [];      // [{meta, detail, error}]\nlet leaguesLoaded = false, leaguesErr = [];\nasync function loadAll(){\n  leagues = []; leaguesErr = []; leaguesLoaded = false; render();\n  const jobs = [];\n  accts.sleeper.forEach(u => jobs.push(sleeperLeagues(u).catch(e => { leaguesErr.push(\"Sleeper \" + u + \": \" + e.message); return []; })));\n  accts.flea.forEach(a => jobs.push(fleaLeagues(a).catch(e => { leaguesErr.push(\"Fleaflicker \" + a.value + \": \" + e.message); return []; })));\n  const metas = (await Promise.all(jobs.concat([loadScoreboard().then(() => [])]))).flat();\n  leagues = metas.map(m => ({meta:m, detail:null, error:null}));\n  leaguesLoaded = true; render();\n  await Promise.all(leagues.map(async L => {\n    try { L.detail = L.meta.platform === \"sleeper\" ? await sleeperDetail(L.meta) : await fleaDetail(L.meta); }\n    catch(e){ L.error = e.message; }\n    if (cur.tab === \"leagues\") render();\n  }));\n  syncAlerts().catch(() => {});\n  const st = await getState().catch(() => null);\n  if (st) $(\"#wk\").textContent = \"Week \" + (st.display_week || st.week);\n}\n\n/* ---------- views ---------- */\nconst cur = {tab:\"leagues\", league:null, newsMine:false};\nfunction setTab(t){ cur.tab = t; cur.league = null; document.querySelectorAll(\"#tabs button\").forEach(b => b.setAttribute(\"aria-selected\", b.dataset.tab === t)); render(); window.scrollTo(0,0); }\n$(\"#bellBtn\").addEventListener(\"click\", () => setTab(cur.tab === \"alerts\" ? \"leagues\" : \"alerts\"));\n$(\"#tabs\").addEventListener(\"click\", e => { const b = e.target.closest(\"button[data-tab]\"); if (b) setTab(b.dataset.tab); });\n\nfunction render(){\n  const v = $(\"#view\");\n  $(\"#bellBtn\").setAttribute(\"aria-pressed\", cur.tab === \"alerts\");\n  if (cur.tab === \"alerts\") return renderAlerts(v);\n  if (cur.tab === \"accounts\") return renderAccounts(v);\n  if (cur.tab === \"news\") return renderNews(v);\n  if (cur.tab === \"trending\") return renderTrending(v);\n  if (cur.league != null) return renderLeague(v, leagues[cur.league]);\n  renderLeagues(v); wireInstall(v);\n}\nfunction hasAccts(){ return accts.sleeper.length + accts.flea.length > 0; }\n\nfunction emptyState(v){\n  v.innerHTML = installCard() + '<h2>Your leagues, one screen</h2><p class=\"muted\">Add a Sleeper username or a Fleaflicker email or league ID. Your rosters, scores and injury flags load straight from the league sites.</p>' + addForm();\n  wireAdd(v);\n}\nfunction renderLeagues(v){\n  if (!hasAccts()) return emptyState(v);\n  let h = installCard();\n  leaguesErr.forEach(e => h += '<div class=\"err\">' + esc(e) + \"</div>\");\n  if (!leaguesLoaded) { v.innerHTML = h + '<p class=\"spin\">Loading your leagues…</p>'; return; }\n  if (!leagues.length) { v.innerHTML = h + '<p class=\"muted\">No leagues found for this season.</p>'; return; }\n  h += '<div class=\"stack\" style=\"margin-top:12px\">';\n  leagues.forEach((L, i) => {\n    const m = L.meta, d = L.detail;\n    h += '<button class=\"card league\" data-l=\"' + i + '\"><div class=\"row1\"><span class=\"name\">' + esc(m.name) + '</span><span class=\"badge\">' + (m.platform === \"sleeper\" ? \"Sleeper\" : \"Fleaflicker\") + \"</span></div>\";\n    if (L.error) h += '<span class=\"small\" style=\"color:var(--bad)\">' + esc(L.error) + \"</span>\";\n    else if (!d) h += '<span class=\"small muted\">Loading scores…</span>';\n    else {\n      const me = d.teams.find(t => t.mine);\n      if (!me) h += '<span class=\"small muted\">Tap to pick your team</span>';\n      else {\n        const g = d.games.find(g => g.a.id === me.id || g.b.id === me.id);\n        h += '<span class=\"small muted\">' + esc(me.name) + \" · \" + me.w + \"-\" + me.l + (me.t ? \"-\" + me.t : \"\") + \"</span>\";\n        if (g) {\n          const mine = g.a.id === me.id ? g.a : g.b, opp = g.a.id === me.id ? g.b : g.a;\n          const ot = d.teams.find(t => t.id === opp.id) || {name:\"Opponent\"};\n          const lead = (mine.pts||0) >= (opp.pts||0);\n          h += '<div class=\"score\"><span class=\"t me\">' + esc(me.name) + '</span><span class=\"p ' + (lead ? \"lead\" : \"\") + '\">' + fmt(mine.pts) + '</span><span class=\"t\">' + esc(ot.name) + '</span><span class=\"p\">' + fmt(opp.pts) + \"</span></div>\";\n        }\n        const hurt = me.roster.filter(p => p.inj && p.slot !== \"ir\");\n        if (hurt.length) h += '<span class=\"small\" style=\"color:var(--warn)\">' + hurt.length + \" player\" + (hurt.length > 1 ? \"s\" : \"\") + \" on the injury report</span>\";\n      }\n    }\n    h += \"</button>\";\n  });\n  v.innerHTML = h + \"</div>\";\n  v.querySelectorAll(\"[data-l]\").forEach(b => b.addEventListener(\"click\", () => { cur.league = +b.dataset.l; cur.team = null; render(); window.scrollTo(0,0); }));\n}\n\n/* ---------- NFL games (live status for every player) ---------- */\nconst TEAM_ALIAS = {WSH:\"WAS\", JAC:\"JAX\", LA:\"LAR\", OAK:\"LV\", SD:\"LAC\"};\nconst tnorm = t => { t = String(t || \"\").toUpperCase(); return TEAM_ALIAS[t] || t; };\nlet nflGames = {}, gamesAt = 0;\nasync function loadScoreboard(){\n  try {\n    const r = await api(\"/api/scoreboard\");\n    const map = {};\n    (r.games || []).forEach(g => { map[tnorm(g.away)] = g; map[tnorm(g.home)] = g; });\n    nflGames = map; gamesAt = Date.now();\n  } catch(e){}\n}\nconst anyLive = () => Object.values(nflGames).some(g => g.state === \"in\");\nfunction gameLine(team){\n  if (!team) return '<span class=\"muted\">Free agent</span>';\n  const t = tnorm(team), g = nflGames[t];\n  if (!gamesAt) return esc(t);\n  if (!g) return esc(t) + ' · <span class=\"muted\">Bye</span>';\n  const opp = tnorm(g.away) === t ? \"@\" + tnorm(g.home) : \"vs \" + tnorm(g.away);\n  if (g.state === \"pre\") return esc(t) + \" \" + esc(opp) + ' · <span class=\"muted\">' + esc(g.detail) + \"</span>\";\n  const sc = tnorm(g.away) + \" \" + g.awayScore + \" – \" + tnorm(g.home) + \" \" + g.homeScore;\n  if (g.state === \"in\") return '<span class=\"live\">LIVE</span> ' + esc(sc) + \" · \" + esc(g.detail);\n  return esc(sc) + ' · <span class=\"muted\">Final</span>';\n}\n\n/* ---------- player rows ---------- */\nlet reg = [];\nfunction playerRow(p, right){\n  const i = reg.push(p) - 1;\n  return '<li><button class=\"prow\" data-i=\"' + i + '\">' +\n    '<span class=\"pos\">' + esc(p.pos || \"–\") + '</span><span class=\"pname\"><b>' + esc(p.name || p.id) + injChip(p.inj) + \"</b><small>\" + gameLine(p.team) + (p.injPart ? \" · \" + esc(p.injPart) : \"\") + \"</small>\" + (p.extra || \"\") + \"</span>\" +\n    '<span class=\"pts\">' + (right == null ? \"\" : right) + \"</span></button></li>\";\n}\nfunction wireRows(v){ v.querySelectorAll(\".prow[data-i]\").forEach(b => b.addEventListener(\"click\", () => openPlayer(reg[+b.dataset.i]))); }\nconst POS_ORDER = {QB:1,RB:2,WR:3,TE:4,K:5,DEF:6,DST:6,\"D/ST\":6};\nconst byPos = (a,b) => (POS_ORDER[a.pos]||9) - (POS_ORDER[b.pos]||9) || String(a.name).localeCompare(String(b.name));\n\n/* ---------- season stats (Sleeper) ---------- */\nlet sstats = null, sstatsP = null;\nfunction getSeasonStats(season){ if (!sstatsP) sstatsP = api(\"/api/sstats?season=\" + season).then(s => (sstats = s)).catch(() => (sstats = {})); return sstatsP; }\nconst SCORE_IDX = {ppr:0, half:1, std:2};\nfunction seasonPts(pid, fmtKey){ const s = sstats && sstats[pid]; if (!s) return null; return {pts:s[SCORE_IDX[fmtKey] || 0], gp:s[3]}; }\n\n/* ---------- Fleaflicker: live lineup for one team ---------- */\nasync function fleaTeamRoster(L, team){\n  try {\n    const r = await api(fq(\"FetchRoster\", {league_id:L.meta.id, team_id:team.id}));\n    const out = [];\n    (r.groups || []).forEach(g => (g.slots || []).forEach(s => {\n      const lp = s.leaguePlayer; if (!lp || !lp.proPlayer) return;\n      const p = lp.proPlayer, inj = p.injury || null, grp = String(g.group || \"\").toUpperCase();\n      const rg = (lp.requestedGames || [])[0] || {};\n      const pts = val(lp.viewingActualPoints) ?? val(rg.pointsActual);\n      out.push({id:String(p.id), name:p.nameFull, pos:p.position, team:p.proTeamAbbreviation,\n        inj: inj ? (inj.typeAbbreviaition || inj.typeAbbreviation || inj.typeFull) : null,\n        injPart: inj ? (inj.description || inj.typeFull) : null,\n        slot: grp === \"START\" ? \"start\" : (grp === \"INJURED\" || grp === \"IR\") ? \"ir\" : \"bench\",\n        pts: pts, avg: val(lp.seasonAverage), tot: val(lp.seasonTotal)});\n    }));\n    if (out.length) { team.roster = out; team.live = true; }\n  } catch(e){ team.liveErr = e.message; }\n}\n\n/* ---------- league view ---------- */\nfunction renderLeague(v, L){\n  reg = [];\n  const m = L.meta, d = L.detail;\n  let h = '<button class=\"back\" id=\"back\">‹ All leagues</button><h2>' + esc(m.name) + \"</h2>\";\n  if (L.error) { v.innerHTML = h + '<div class=\"err\">' + esc(L.error) + \"</div>\"; return wireBack(v); }\n  if (!d) { v.innerHTML = h + '<p class=\"spin\">Loading…</p>'; return wireBack(v); }\n  const sub = cur.sub || \"team\";\n  h += '<div class=\"seg sub\" role=\"tablist\">' + [[\"team\",\"My team\"],[\"fa\",\"Free agents\"],[\"league\",\"League\"]].map(x => '<button type=\"button\" data-sub=\"' + x[0] + '\" aria-pressed=\"' + (sub === x[0]) + '\">' + x[1] + \"</button>\").join(\"\") + \"</div>\";\n  let me = cur.team ? d.teams.find(t => t.id === cur.team) : d.teams.find(t => t.mine);\n  if (sub === \"team\") {\n    h += '<label for=\"teamPick\" style=\"display:block;margin-top:12px\">Team</label><select id=\"teamPick\">' + (me ? \"\" : '<option value=\"\">Pick your team…</option>') +\n      d.teams.map(t => '<option value=\"' + esc(t.id) + '\"' + (me && me.id === t.id ? \" selected\" : \"\") + \">\" + esc(t.name) + (t.owner ? \" (\" + esc(t.owner) + \")\" : \"\") + \"</option>\").join(\"\") + \"</select>\";\n    if (me) {\n      if (m.platform === \"flea\" && !me.live && !me.liveLoading && !me.liveErr) { me.liveLoading = true; fleaTeamRoster(L, me).then(() => { me.liveLoading = false; if (cur.league === leagues.indexOf(L)) render(); }); }\n      const g = d.games.find(g => g.a.id === me.id || g.b.id === me.id);\n      if (g) {\n        const mine = g.a.id === me.id ? g.a : g.b, opp = g.a.id === me.id ? g.b : g.a;\n        const ot = d.teams.find(t => t.id === opp.id) || {name:\"Opponent\"};\n        h += '<div class=\"card score\" style=\"margin-top:12px\"><span class=\"t me\">' + esc(me.name) + '</span><span class=\"p ' + ((mine.pts||0) >= (opp.pts||0) ? \"lead\" : \"\") + '\">' + fmt(mine.pts) + '</span><span class=\"t\">' + esc(ot.name) + '</span><span class=\"p\">' + fmt(opp.pts) + \"</span></div>\";\n      }\n      const right = p => {\n        if (p.pts != null) return fmt(p.pts);\n        if (m.platform === \"sleeper\") { const s = seasonPts(p.id, d.scoring); return s && s.gp ? '<span class=\"avg\">' + fmt(s.pts / s.gp) + \"<small>avg</small></span>\" : \"\"; }\n        return p.avg != null ? '<span class=\"avg\">' + fmt(p.avg) + \"<small>avg</small></span>\" : \"\";\n      };\n      const split = m.platform === \"sleeper\" || me.live;\n      if (split) {\n        const st = me.roster.filter(p => p.slot === \"start\").sort(byPos), bn = me.roster.filter(p => p.slot === \"bench\").sort(byPos), ir = me.roster.filter(p => p.slot === \"ir\");\n        h += \"<h3>Starters\" + (d.week ? \" · Week \" + d.week : \"\") + '</h3><ul class=\"plist\">' + st.map(p => playerRow(p, right(p))).join(\"\") + \"</ul>\";\n        h += '<h3>Bench</h3><ul class=\"plist\">' + bn.map(p => playerRow(p, right(p))).join(\"\") + \"</ul>\";\n        if (ir.length) h += '<h3>IR</h3><ul class=\"plist\">' + ir.map(p => playerRow(p, \"\")).join(\"\") + \"</ul>\";\n      } else {\n        h += \"<h3>Roster\" + (me.liveLoading ? \" · loading live points…\" : \"\") + '</h3><ul class=\"plist\">' + me.roster.slice().sort(byPos).map(p => playerRow(p, right(p))).join(\"\") + \"</ul>\";\n      }\n      h += '<p class=\"small muted\">' + (anyLive() ? \"Games in progress · updates every minute\" : \"Updated \" + new Date().toLocaleTimeString([], {hour:\"numeric\", minute:\"2-digit\"})) + \"</p>\";\n    }\n  } else if (sub === \"fa\") {\n    const pos = cur.faPos || \"ALL\";\n    h += '<div class=\"chips posf\">' + [\"ALL\",\"QB\",\"RB\",\"WR\",\"TE\",\"K\",\"DEF\"].map(x => '<button type=\"button\" class=\"chip' + (pos === x ? \" on\" : \"\") + '\" data-pos=\"' + x + '\">' + x + \"</button>\").join(\"\") + '</div><div id=\"fa\"><p class=\"spin\">Loading free agents…</p></div>';\n  } else {\n    if (d.games.length) {\n      h += \"<h3>Matchups\" + (d.week ? \" · Week \" + d.week : \"\") + '</h3><div class=\"stack\">';\n      d.games.forEach(g => {\n        const A = d.teams.find(t => t.id === g.a.id) || {name:\"Team\"}, B = d.teams.find(t => t.id === g.b.id) || {name:\"Team\"};\n        const aLead = (g.a.pts||0) > (g.b.pts||0), bLead = (g.b.pts||0) > (g.a.pts||0);\n        h += '<div class=\"card score\"><span class=\"t' + (me && A.id === me.id ? \" me\" : \"\") + '\">' + esc(A.name) + '</span><span class=\"p ' + (aLead ? \"lead\" : \"\") + '\">' + fmt(g.a.pts) + '</span><span class=\"t' + (me && B.id === me.id ? \" me\" : \"\") + '\">' + esc(B.name) + '</span><span class=\"p ' + (bLead ? \"lead\" : \"\") + '\">' + fmt(g.b.pts) + \"</span></div>\";\n      });\n      h += \"</div>\";\n    }\n    const stand = d.teams.slice().sort((a,b) => b.w - a.w || (b.pf||0) - (a.pf||0));\n    h += '<h3>Standings</h3><ul class=\"plist\">' + stand.map((t,i) => '<li><div class=\"prow\" style=\"grid-template-columns:28px 1fr auto\"><span class=\"muted\" style=\"font-variant-numeric:tabular-nums\">' + (i+1) + '</span><span class=\"pname\"><b' + (me && t.id === me.id ? ' class=\"me\"' : \"\") + \">\" + esc(t.name) + \"</b><small>\" + t.w + \"-\" + t.l + (t.t ? \"-\" + t.t : \"\") + '</small></span><span class=\"small muted\" style=\"font-variant-numeric:tabular-nums\">' + fmt(t.pf) + \" PF</span></div></li>\").join(\"\") + \"</ul>\";\n  }\n  v.innerHTML = h;\n  wireBack(v);\n  v.querySelectorAll(\"[data-sub]\").forEach(b => b.addEventListener(\"click\", () => { cur.sub = b.dataset.sub; render(); }));\n  const sel = v.querySelector(\"#teamPick\");\n  if (sel) sel.addEventListener(\"change\", () => {\n    cur.team = sel.value || null;\n    if (m.platform === \"flea\" && cur.team) { m.myTeam = cur.team; d.teams.forEach(t => t.mine = t.id === cur.team); rememberFleaTeam(m, cur.team); }\n    render();\n  });\n  v.querySelectorAll(\"[data-pos]\").forEach(b => b.addEventListener(\"click\", () => { cur.faPos = b.dataset.pos; render(); }));\n  wireRows(v);\n  if (sub === \"fa\") loadFreeAgents(L, cur.faPos || \"ALL\");\n}\n\n/* ---------- free agents ---------- */\nasync function loadFreeAgents(L, pos){\n  const el = () => $(\"#fa\");\n  const token = (cur.faToken = Math.random());\n  try {\n    let list = [];\n    if (L.meta.platform === \"sleeper\") {\n      const d = L.detail;\n      await Promise.all([getPlayers(), getSeasonStats(L.meta.season)]);\n      const taken = new Set(); d.teams.forEach(t => t.roster.forEach(p => taken.add(p.id)));\n      for (const id in players) {\n        if (taken.has(id)) continue;\n        const p = players[id]; if (pos !== \"ALL\" && p[1] !== pos) continue;\n        if (!p[2] && p[1] !== \"DEF\") continue;\n        const s = seasonPts(id, d.scoring); if (!s || !s.pts) continue;\n        list.push({id, name:p[0], pos:p[1], team:p[2], inj:p[3], injPart:p[4], tot:s.pts, avg:s.gp ? s.pts / s.gp : null, gp:s.gp});\n      }\n      list.sort((a,b) => b.tot - a.tot); list = list.slice(0, 40);\n    } else {\n      const params = {league_id:L.meta.id, \"filter.free_agent_only\":\"true\", sort:\"SORT_SEASON_TOTAL\"};\n      if (pos !== \"ALL\") params[\"filter.position.eligibility\"] = pos === \"DEF\" ? \"D/ST\" : pos;\n      const r = await api(fq(\"FetchPlayerListing\", params));\n      list = (r.players || []).map(x => {\n        const p = x.proPlayer || {}, inj = p.injury || null;\n        return {id:String(p.id), name:p.nameFull, pos:p.position, team:p.proTeamAbbreviation,\n          inj: inj ? (inj.typeAbbreviaition || inj.typeAbbreviation || inj.typeFull) : null, injPart: inj ? (inj.description || inj.typeFull) : null,\n          tot: val(x.seasonTotal), avg: val(x.seasonAverage)};\n      });\n    }\n    if (token !== cur.faToken || !el()) return;\n    if (!list.length) { el().innerHTML = '<p class=\"muted\">No free agents found' + (pos !== \"ALL\" ? \" at \" + pos : \"\") + \".</p>\"; return; }\n    list.forEach(p => p.extra = p.avg != null ? '<small class=\"muted\"> · ' + fmt(p.avg) + \" per game</small>\" : \"\");\n    el().innerHTML = '<p class=\"small muted\" style=\"margin:10px 0 6px\">Ranked by season points' + (L.meta.platform === \"sleeper\" ? \" (\" + ({ppr:\"PPR\", half:\"half PPR\", std:\"standard\"}[L.detail.scoring] || \"PPR\") + \")\" : \"\") + '</p><ul class=\"plist\">' + list.map(p => playerRow(p, fmt(p.tot))).join(\"\") + \"</ul>\";\n    wireRows(el());\n  } catch(e){ if (el()) el().innerHTML = '<div class=\"err\">Couldn’t load free agents: ' + esc(e.message) + \"</div>\"; }\n}\nfunction wireBack(v){ v.querySelector(\"#back\").addEventListener(\"click\", () => { cur.league = null; cur.sub = \"team\"; render(); }); }\nfunction rememberFleaTeam(m, team){\n  try { const s = JSON.parse(localStorage.getItem(KEY + \".fleaTeams\") || \"{}\"); s[m.id] = team; localStorage.setItem(KEY + \".fleaTeams\", JSON.stringify(s)); } catch(e){}\n}\nfunction fleaTeamFor(id){ try { return (JSON.parse(localStorage.getItem(KEY + \".fleaTeams\") || \"{}\"))[id] || null; } catch(e){ return null; } }\n\n/* ---------- player sheet ---------- */\nfunction ago(d){\n  const t = new Date(d).getTime(); if (!t) return \"\";\n  const m = Math.round((Date.now() - t) / 60000);\n  if (m < 60) return m + \"m ago\"; if (m < 1440) return Math.round(m/60) + \"h ago\"; return Math.round(m/1440) + \"d ago\";\n}\nasync function openPlayer(pl){\n  const sh = $(\"#sheet\"), p = $(\"#sheetPanel\");\n  let stats = \"\";\n  const cells = [];\n  if (pl.pts != null) cells.push([\"This week\", fmt(pl.pts)]);\n  if (pl.tot != null) cells.push([\"Season\", fmt(pl.tot)]);\n  if (pl.avg != null) cells.push([\"Per game\", fmt(pl.avg)]);\n  if (cells.length) stats = '<div class=\"statrow\">' + cells.map(c => '<div><small>' + c[0] + \"</small><b>\" + c[1] + \"</b></div>\").join(\"\") + \"</div>\";\n  p.innerHTML = '<button class=\"back\" id=\"closeSheet\">✕ Close</button><h2 style=\"margin-top:6px\">' + esc(pl.name) + injChip(pl.inj) + '</h2><p class=\"muted small\" style=\"margin:0\">' + esc(pl.pos || \"\") + \" · \" + gameLine(pl.team) + (pl.injPart ? \" · \" + esc(pl.injPart) : \"\") + \"</p>\" + stats + '<h3>Latest news</h3><div id=\"pnews\"><p class=\"spin\">Searching headlines…</p></div>';\n  sh.hidden = false;\n  p.querySelector(\"#closeSheet\").addEventListener(\"click\", closeSheet);\n  try {\n    const r = await api(\"/api/news?q=\" + encodeURIComponent('\"' + pl.name + '\" NFL'));\n    const items = (r.items || []).slice(0, 10);\n    $(\"#pnews\").innerHTML = items.length ? '<div class=\"news card\" style=\"padding:0\">' + items.map(n => '<a href=\"' + esc(n.link) + '\" target=\"_blank\" rel=\"noopener\"><b>' + esc(n.title) + \"</b><small>\" + esc(n.source || \"\") + (n.date ? \" · \" + ago(n.date) : \"\") + \"</small></a>\").join(\"\") + \"</div>\" : '<p class=\"muted\">No recent headlines found.</p>';\n  } catch(e){ $(\"#pnews\").innerHTML = '<div class=\"err\">Couldn’t load headlines: ' + esc(e.message) + \"</div>\"; }\n}\nfunction closeSheet(){ $(\"#sheet\").hidden = true; }\n$(\"#sheet\").addEventListener(\"click\", e => { if (e.target.id === \"sheet\") closeSheet(); });\ndocument.addEventListener(\"keydown\", e => { if (e.key === \"Escape\") closeSheet(); });\n\n/* ---------- my players index (for headlines + trending) ---------- */\nfunction myPlayers(){\n  const out = [];\n  leagues.forEach(L => { const d = L.detail; if (!d) return; const me = d.teams.find(t => t.mine); if (me) me.roster.forEach(p => p.name && out.push(p.name)); });\n  return [...new Set(out)];\n}\n\n/* ---------- headlines ---------- */\nlet headlines = null;\nasync function renderNews(v){\n  v.innerHTML = '<h2>NFL headlines</h2><label class=\"toggle\"><input type=\"checkbox\" id=\"mineOnly\"' + (cur.newsMine ? \" checked\" : \"\") + '> Only stories about my players</label><div id=\"hl\"><p class=\"spin\">Loading headlines…</p></div>';\n  v.querySelector(\"#mineOnly\").addEventListener(\"change\", e => { cur.newsMine = e.target.checked; drawNews(); });\n  try { if (!headlines) headlines = await api(\"/api/headlines\"); drawNews(); }\n  catch(e){ $(\"#hl\").innerHTML = '<div class=\"err\">Couldn’t load headlines: ' + esc(e.message) + \"</div>\"; }\n}\nfunction drawNews(){\n  const el = $(\"#hl\"); if (!el || !headlines) return;\n  const mine = myPlayers();\n  const rx = mine.length ? new RegExp(\"\\\\b(\" + mine.map(n => n.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\")).join(\"|\") + \")\\\\b\", \"gi\") : null;\n  let items = (headlines.items || []).map(a => {\n    const text = a.title + \" \" + (a.desc || \"\") + \" \" + (a.athletes || []).join(\" \");\n    const hit = rx ? (text.match(rx) || []) : [];\n    if (rx) rx.lastIndex = 0;\n    return Object.assign({hit:[...new Set(hit)]}, a);\n  });\n  if (cur.newsMine) items = items.filter(a => a.hit.length);\n  if (!items.length) { el.innerHTML = '<p class=\"muted\">' + (cur.newsMine ? (mine.length ? \"None of today’s top stories mention your players.\" : \"Load your leagues first so we know who your players are.\") : \"No headlines right now.\") + \"</p>\"; return; }\n  el.innerHTML = '<div class=\"news card\" style=\"padding:0\">' + items.map(a => '<a href=\"' + esc(a.link) + '\" target=\"_blank\" rel=\"noopener\"><b>' + esc(a.title) + \"</b>\" + (a.desc ? '<span class=\"small muted\" style=\"display:block;margin:2px 0\">' + esc(a.desc) + \"</span>\" : \"\") + \"<small>ESPN\" + (a.date ? \" · \" + ago(a.date) : \"\") + (a.hit.length ? ' · <span class=\"mine\">' + esc(a.hit.join(\", \")) + \"</span>\" : \"\") + \"</small></a>\").join(\"\") + \"</div>\";\n}\n\n/* ---------- trending ---------- */\nasync function renderTrending(v){\n  reg = [];\n  v.innerHTML = '<h2>Most added, last 24 hours</h2><p class=\"muted small\" style=\"margin-top:-4px\">Adds across all Sleeper leagues. We check each one against your leagues so you can see who’s still on waivers.</p><div id=\"tr\"><p class=\"spin\">Loading…</p></div>';\n  try {\n    const [tr] = await Promise.all([api(\"/api/sleeper/players/nfl/trending/add?lookback_hours=24&limit=25\"), getPlayers(), gamesAt ? null : loadScoreboard()]);\n    const ready = leagues.filter(L => L.detail);\n    const rows = tr.map(t => {\n      const p = players[t.player_id] || [t.player_id, \"\", \"\"];\n      const chips = ready.map(L => {\n        const taken = L.meta.platform === \"sleeper\"\n          ? L.detail.teams.some(tm => tm.roster.some(r => r.id === t.player_id))\n          : L.detail.teams.some(tm => tm.roster.some(r => norm(r.name) === norm(p[0])));\n        return taken ? '<span class=\"chip\">Rostered in ' + esc(L.meta.name) + \"</span>\" : '<span class=\"chip free\">Free in ' + esc(L.meta.name) + \"</span>\";\n      }).join(\"\");\n      return playerRow({id:t.player_id, name:p[0], pos:p[1], team:p[2], inj:p[3], injPart:p[4], extra: chips ? '<span class=\"chips\">' + chips + \"</span>\" : \"\"}, '<span class=\"small muted\" style=\"font:600 14px var(--body)\">+' + Number(t.count).toLocaleString() + \"</span>\");\n    }).join(\"\");\n    $(\"#tr\").innerHTML = '<ul class=\"plist\">' + rows + \"</ul>\" + (hasAccts() && !ready.length ? '<p class=\"muted small\">Your leagues are still loading. Reopen this tab to see who’s free.</p>' : \"\");\n    wireRows(v);\n  } catch(e){ $(\"#tr\").innerHTML = '<div class=\"err\">Couldn’t load trending players: ' + esc(e.message) + \"</div>\"; }\n}\n\n/* ---------- accounts ---------- */\nlet addMode = \"sleeper\";\nfunction addForm(){\n  return '<form class=\"add card\" id=\"addForm\"><div class=\"seg\" role=\"group\" aria-label=\"Platform\">' +\n    '<button type=\"button\" data-m=\"sleeper\" aria-pressed=\"' + (addMode === \"sleeper\") + '\">Sleeper</button>' +\n    '<button type=\"button\" data-m=\"flea\" aria-pressed=\"' + (addMode === \"flea\") + '\">Fleaflicker</button></div>' +\n    (addMode === \"sleeper\"\n      ? '<label for=\"acctIn\">Sleeper username</label><input id=\"acctIn\" autocomplete=\"off\" autocapitalize=\"off\" placeholder=\"e.g. gridironGreg\" required>'\n      : '<label for=\"acctIn\">Fleaflicker email or league ID</label><input id=\"acctIn\" autocomplete=\"off\" autocapitalize=\"off\" placeholder=\"you@email.com or 312876\" required><span class=\"small muted\">The league ID is the number in your league’s Fleaflicker web address.</span>') +\n    '<button class=\"btn\" type=\"submit\">Add</button></form>';\n}\nfunction wireAdd(v){\n  const f = v.querySelector(\"#addForm\");\n  f.querySelectorAll(\"[data-m]\").forEach(b => b.addEventListener(\"click\", () => { addMode = b.dataset.m; render(); }));\n  f.addEventListener(\"submit\", e => {\n    e.preventDefault();\n    const x = f.querySelector(\"#acctIn\").value.trim(); if (!x) return;\n    if (addMode === \"sleeper\") { if (!accts.sleeper.includes(x)) accts.sleeper.push(x); }\n    else { const type = /^\\d+$/.test(x) ? \"league\" : \"email\"; if (!accts.flea.some(a => a.value === x)) accts.flea.push({type, value:x}); }\n    saveAccts(accts); setTab(\"leagues\"); loadAll();\n  });\n}\nfunction renderAccounts(v){\n  let h = \"<h2>Accounts</h2>\";\n  const list = accts.sleeper.map((u,i) => ({label:u, plat:\"Sleeper\", k:\"s\", i})).concat(accts.flea.map((a,i) => ({label:(a.type === \"league\" ? \"League \" : \"\") + a.value, plat:\"Fleaflicker\", k:\"f\", i})));\n  if (list.length) h += '<div class=\"card\">' + list.map(a => '<div class=\"acct\"><span><b>' + esc(a.label) + '</b> <span class=\"badge\">' + a.plat + '</span></span><button class=\"icon\" data-rm=\"' + a.k + a.i + '\">Remove</button></div>').join(\"\") + \"</div>\";\n  h += \"<h3>Add another</h3>\" + addForm();\n  h += '<p class=\"small muted\">Accounts are saved only in this browser. Nothing is sent anywhere except the league sites themselves.</p>';\n  v.innerHTML = h;\n  v.querySelectorAll(\"[data-rm]\").forEach(b => b.addEventListener(\"click\", () => {\n    const k = b.dataset.rm[0], i = +b.dataset.rm.slice(1);\n    if (k === \"s\") accts.sleeper.splice(i,1); else accts.flea.splice(i,1);\n    saveAccts(accts); loadAll(); render();\n  }));\n  wireAdd(v);\n}\n\n/* ---------- push alerts ---------- */\nconst pushOK = \"serviceWorker\" in navigator && \"PushManager\" in window && \"Notification\" in window;\nasync function post(path, body){\n  const r = await fetch(path, {method:\"POST\", headers:{\"content-type\":\"application/json\"}, body:JSON.stringify(body)});\n  let j = {}; try { j = await r.json(); } catch(e){}\n  if (!r.ok) throw new Error(j.error || (\"Request failed (\" + r.status + \")\"));\n  return j;\n}\nfunction alertPrefs(){ try { return Object.assign({mine:true, fa:true, faPos:\"ALL\"}, JSON.parse(localStorage.getItem(KEY + \".alerts\") || \"{}\")); } catch(e){ return {mine:true, fa:true, faPos:\"ALL\"}; } }\nfunction saveAlertPrefs(p){ try { localStorage.setItem(KEY + \".alerts\", JSON.stringify(p)); } catch(e){} }\nfunction b64uBytes(s){ s = s.replace(/-/g, \"+\").replace(/_/g, \"/\"); while (s.length % 4) s += \"=\"; const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return a; }\nasync function getSub(){\n  if (!pushOK) return null;\n  try { const reg = await navigator.serviceWorker.getRegistration(\"/\"); return reg ? await reg.pushManager.getSubscription() : null; } catch(e){ return null; }\n}\nfunction watchList(){\n  const ids = new Set(), names = new Set();\n  leagues.forEach(L => {\n    const d = L.detail; if (!d) return;\n    const me = d.teams.find(t => t.mine); if (!me) return;\n    me.roster.forEach(p => { if (L.meta.platform === \"sleeper\") ids.add(String(p.id)); else if (p.name) names.add(norm(p.name) + \"|\" + (p.pos || \"\")); });\n  });\n  return {ids:[...ids], names:[...names], leagues: leagues.map(L => ({p:L.meta.platform, id:L.meta.id, name:L.meta.name}))};\n}\nlet alertState = {sub:null, watching:null, msg:\"\", busy:false, list:null};\nasync function syncAlerts(sub){\n  sub = sub || await getSub(); if (!sub) return null;\n  const r = await post(\"/api/push/subscribe\", Object.assign({sub: sub.toJSON(), prefs: alertPrefs()}, watchList()));\n  alertState.watching = r;\n  return r;\n}\nasync function enableAlerts(){\n  const perm = await Notification.requestPermission();\n  if (perm !== \"granted\") throw new Error(\"Notifications are blocked for this site. Allow them in your browser's site settings for this page, then try again.\");\n  const reg = await navigator.serviceWorker.register(\"/sw.js\");\n  await navigator.serviceWorker.ready;\n  const {key} = await api(\"/api/push/key\");\n  let sub = await reg.pushManager.getSubscription();\n  let lastKey = null; try { lastKey = localStorage.getItem(KEY + \".vapid\"); } catch(e){}\n  if (sub && lastKey && lastKey !== key) { await sub.unsubscribe(); sub = null; }\n  if (!sub) sub = await reg.pushManager.subscribe({userVisibleOnly:true, applicationServerKey:b64uBytes(key)});\n  try { localStorage.setItem(KEY + \".vapid\", key); } catch(e){}\n  await syncAlerts(sub);\n  return sub;\n}\nfunction fmtWhen(t){ const d = new Date(t); return d.toLocaleDateString([], {weekday:\"short\"}) + \" \" + d.toLocaleTimeString([], {hour:\"numeric\", minute:\"2-digit\"}); }\n\nasync function renderAlerts(v){\n  const prefs = alertPrefs();\n  let h = \"<h2>Alerts</h2>\";\n  if (!pushOK) {\n    v.innerHTML = h + '<div class=\"card\"><p style=\"margin:0\">This browser can’t receive alerts.</p><p class=\"small muted\" style=\"margin:8px 0 0\">On iPhone, tap Share, then Add to Home Screen, and open Snap Count from your home screen. On Android, use Chrome.</p></div>';\n    return;\n  }\n  const sub = alertState.sub = await getSub();\n  if (cur.tab !== \"alerts\") return;\n  if (!sub) {\n    h += '<div class=\"card alertpitch\"><p style=\"margin:0 0 10px\"><b>Get a notification on this phone when:</b></p><ul class=\"ticks\"><li>A player on your roster is downgraded, ruled out, placed on IR, comes off the injury report, or gets traded</li><li>A starter is ruled out and his backup is a free agent in one of your leagues</li><li>A free agent’s projected points jump, especially at QB</li></ul>' +\n      '<button class=\"btn\" id=\"alOn\" style=\"width:100%;margin-top:6px\">Turn on alerts</button>' +\n      (hasAccts() ? \"\" : '<p class=\"small muted\" style=\"margin:10px 0 0\">Add your leagues under Accounts first so we know who your players are.</p>') + \"</div>\";\n    if (alertState.msg) h += '<div class=\"err\" style=\"margin-top:10px\">' + esc(alertState.msg) + \"</div>\";\n    v.innerHTML = h;\n    v.querySelector(\"#alOn\").addEventListener(\"click\", async e => {\n      e.target.disabled = true; e.target.textContent = \"Turning on…\"; alertState.msg = \"\";\n      try { await enableAlerts(); } catch(err){ alertState.msg = err.message; }\n      render();\n    });\n    return;\n  }\n  const w = watchList();\n  const nMine = w.ids.length + w.names.length;\n  h += '<div class=\"card\"><div class=\"alstat\"><span class=\"dot\"></span><b>Alerts are on for this phone</b></div><p class=\"small muted\" style=\"margin:6px 0 0\">' +\n    (nMine ? \"Watching \" + nMine + \" of your players across \" + w.leagues.length + \" league\" + (w.leagues.length === 1 ? \"\" : \"s\") + \".\" : \"Your leagues are still loading.\") +\n    \" QBs are checked every minute, other positions every 3 minutes.</p></div>\";\n  h += \"<h3>What to send</h3>\" + '<div class=\"card stackc\">' +\n    '<label class=\"toggle\"><input type=\"checkbox\" id=\"alMine\"' + (prefs.mine ? \" checked\" : \"\") + \"> My players: injuries, status changes and trades</label>\" +\n    '<label class=\"toggle\"><input type=\"checkbox\" id=\"alFa\"' + (prefs.fa ? \" checked\" : \"\") + \"> Free agents: new starters and projection jumps</label>\" +\n    '<div class=\"seg\" role=\"group\" aria-label=\"Free agent positions\"><button type=\"button\" data-fp=\"ALL\" aria-pressed=\"' + (prefs.faPos === \"ALL\") + '\">All positions</button><button type=\"button\" data-fp=\"QB\" aria-pressed=\"' + (prefs.faPos === \"QB\") + '\">QBs only</button></div></div>';\n  h += '<div class=\"btnrow\"><button class=\"btn ghost\" id=\"alTest\">Send a test alert</button><button class=\"btn ghost\" id=\"alOff\">Turn off</button></div>';\n  if (alertState.msg) h += '<p class=\"small\" style=\"margin:8px 0 0\">' + esc(alertState.msg) + \"</p>\";\n  h += '<h3>Recent alerts</h3><div id=\"alList\"><p class=\"spin\">Loading…</p></div>';\n  v.innerHTML = h;\n  const savePrefs = async p => { saveAlertPrefs(p); alertState.msg = \"\"; try { await syncAlerts(sub); } catch(e){ alertState.msg = e.message; } render(); };\n  v.querySelector(\"#alMine\").addEventListener(\"change\", e => savePrefs(Object.assign(alertPrefs(), {mine:e.target.checked})));\n  v.querySelector(\"#alFa\").addEventListener(\"change\", e => savePrefs(Object.assign(alertPrefs(), {fa:e.target.checked})));\n  v.querySelectorAll(\"[data-fp]\").forEach(b => b.addEventListener(\"click\", () => savePrefs(Object.assign(alertPrefs(), {faPos:b.dataset.fp}))));\n  v.querySelector(\"#alTest\").addEventListener(\"click\", async e => {\n    e.target.disabled = true; e.target.textContent = \"Sending…\";\n    try { await syncAlerts(sub); await post(\"/api/push/test\", {endpoint: sub.endpoint}); alertState.msg = \"Test sent. It should show up on this phone in a few seconds.\"; }\n    catch(err){ alertState.msg = err.message; }\n    render();\n  });\n  v.querySelector(\"#alOff\").addEventListener(\"click\", async () => {\n    try { await post(\"/api/push/unsubscribe\", {endpoint: sub.endpoint}); } catch(e){}\n    try { await sub.unsubscribe(); } catch(e){}\n    alertState.msg = \"\"; render();\n  });\n  try {\n    const r = await api(\"/api/push/alerts?e=\" + encodeURIComponent(sub.endpoint));\n    const list = r.alerts || [], el = $(\"#alList\"); if (!el) return;\n    el.innerHTML = list.length ? '<div class=\"news card\" style=\"padding:0\">' + list.map(a => '<div class=\"alitem\"><b>' + esc(a.title) + \"</b><span>\" + esc(a.body) + \"</span><small>\" + fmtWhen(a.t) + \"</small></div>\").join(\"\") + \"</div>\" : '<p class=\"muted small\">Nothing yet. You’ll see every alert here too.</p>';\n  } catch(e){ const el = $(\"#alList\"); if (el) el.innerHTML = '<div class=\"err\">Couldn’t load your alerts: ' + esc(e.message) + \"</div>\"; }\n}\nif (pushOK) navigator.serviceWorker.addEventListener(\"message\", e => { if (e.data && e.data.open === \"alerts\") setTab(\"alerts\"); });\n\n/* ---------- install as an app ---------- */\nlet installEvt = null;\nconst isInstalled = () => { try { return matchMedia(\"(display-mode: standalone)\").matches || navigator.standalone === true; } catch(e){ return false; } };\nwindow.addEventListener(\"beforeinstallprompt\", e => { e.preventDefault(); installEvt = e; if (cur.tab === \"leagues\" && cur.league == null) render(); });\nwindow.addEventListener(\"appinstalled\", () => { installEvt = null; render(); });\nfunction installCard(){\n  if (isInstalled() || !installEvt) return \"\";\n  return '<div class=\"card install\"><img src=\"/icon-192.png\" alt=\"\"><div><b>Get the Snap Count app</b><span>Its own icon, full screen, and alerts.</span></div><button class=\"btn\" id=\"installBtn\">Install</button></div>';\n}\nfunction wireInstall(v){\n  const b = v.querySelector(\"#installBtn\"); if (!b) return;\n  b.addEventListener(\"click\", async () => { if (!installEvt) return; installEvt.prompt(); try { await installEvt.userChoice; } catch(e){} installEvt = null; render(); });\n}\nif (\"serviceWorker\" in navigator) window.addEventListener(\"load\", () => navigator.serviceWorker.register(\"/sw.js\").catch(() => {}));\n\n/* ---------- boot ---------- */\naccts.flea.forEach(a => { if (a.type === \"league\") a.team = fleaTeamFor(a.value); });\nif (location.hash === \"#alerts\") { cur.tab = \"alerts\"; try { history.replaceState(null, \"\", location.pathname); } catch(e){} }\nrender();\nasync function refreshLive(){\n  if (document.hidden || !$(\"#sheet\").hidden || document.activeElement && document.activeElement.tagName === \"SELECT\") return;\n  await loadScoreboard();\n  if (!anyLive() || cur.tab !== \"leagues\") return;\n  const targets = cur.league != null ? [leagues[cur.league]] : leagues;\n  await Promise.all(targets.filter(Boolean).map(async L => {\n    try {\n      const keep = L.detail && L.detail.teams.find(t => t.mine || t.id === cur.team);\n      const fresh = L.meta.platform === \"sleeper\" ? await sleeperDetail(L.meta) : await fleaDetail(L.meta);\n      if (keep) { const nt = fresh.teams.find(t => t.id === keep.id); if (nt && L.meta.platform === \"flea\") await fleaTeamRoster(L, nt); }\n      L.detail = fresh;\n    } catch(e){}\n  }));\n  if (cur.tab === \"leagues\" && (cur.sub || \"team\") !== \"fa\") render();\n}\nsetInterval(refreshLive, 60000);\nif (hasAccts()) loadAll(); else getState().then(st => $(\"#wk\").textContent = \"Week \" + (st.display_week || st.week)).catch(() => {});\n</script>\n</body>\n</html>\n";

const FLEA_OK = new Set([
  "FetchUserLeagues", "FetchLeagueStandings", "FetchLeagueScoreboard", "FetchLeagueRosters",
  "FetchRoster", "FetchLeagueBoxscore", "FetchLeagueActivity", "FetchLeagueTransactions", "FetchPlayerListing"
]);
const UA = { "User-Agent": "SnapCount/1.0 (fantasy dashboard)", "Accept": "application/json" };
const FANTASY_POS = new Set(["QB", "RB", "WR", "TE", "K", "DEF"]);

function json(data, status = 200, maxAge = 60) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "public, max-age=" + maxAge }
  });
}

// Fetch upstream with the edge cache, so many users don't hammer the league sites.
async function cached(ctx, key, ttl, produce) {
  const cache = caches.default;
  const req = new Request("https://snapcount.cache/" + key);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await produce();
  if (res.status === 200) {
    const copy = new Response(res.clone().body, res);
    copy.headers.set("cache-control", "public, max-age=" + ttl);
    ctx.waitUntil(cache.put(req, copy));
  }
  return res;
}

async function upstream(url, ttl) {
  const r = await fetch(url, { headers: UA });
  if (!r.ok) return json({ error: "The league site answered " + r.status + " for this request." }, r.status === 404 ? 404 : 502, 0);
  const body = await r.text();
  return new Response(body, { status: 200, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "public, max-age=" + ttl } });
}

// Sleeper's full player file is ~5 MB; slim it to what the app shows.
async function slimPlayers() {
  const r = await fetch("https://api.sleeper.app/v1/players/nfl", { headers: UA });
  if (!r.ok) return json({ error: "Sleeper player list unavailable (" + r.status + ")" }, 502, 0);
  const all = await r.json();
  const out = {};
  for (const id in all) {
    const p = all[id];
    const pos = p.position || (p.fantasy_positions || [])[0];
    if (!FANTASY_POS.has(pos)) continue;
    if (!p.active && !p.team && pos !== "DEF") continue;
    const name = p.full_name || [p.first_name, p.last_name].filter(Boolean).join(" ");
    out[id] = [name, pos, p.team || "", p.injury_status || null, p.injury_body_part || null];
  }
  return json(out, 200, 21600);
}

function decode(s) {
  return String(s || "")
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
    .trim();
}
function tag(block, name) {
  const m = block.match(new RegExp("<" + name + "[^>]*>([\\s\\S]*?)</" + name + ">"));
  return m ? decode(m[1]) : "";
}

async function playerNews(q) {
  const url = "https://news.google.com/rss/search?q=" + encodeURIComponent(q + " when:14d") + "&hl=en-US&gl=US&ceid=US:en";
  const r = await fetch(url, { headers: { "User-Agent": UA["User-Agent"] } });
  if (!r.ok) return json({ error: "News search unavailable (" + r.status + ")" }, 502, 0);
  const xml = await r.text();
  const items = [];
  const re = /<item>([\s\S]*?)<\/item>/g;
  let m;
  while ((m = re.exec(xml)) && items.length < 15) {
    const b = m[1];
    const source = tag(b, "source");
    let title = tag(b, "title");
    if (source && title.endsWith(" - " + source)) title = title.slice(0, -(source.length + 3));
    const link = tag(b, "link");
    if (!/^https?:\/\//.test(link)) continue;
    items.push({ title, link, source, date: tag(b, "pubDate") });
  }
  items.sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0));
  return json({ items }, 200, 900);
}

async function headlines() {
  const r = await fetch("https://site.api.espn.com/apis/site/v2/sports/football/nfl/news?limit=50", { headers: UA });
  if (!r.ok) return json({ error: "ESPN headlines unavailable (" + r.status + ")" }, 502, 0);
  const d = await r.json();
  const items = (d.articles || []).map(a => ({
    title: a.headline,
    desc: a.description || "",
    link: (a.links && a.links.web && a.links.web.href) || "",
    date: a.published,
    athletes: (a.categories || []).filter(c => c.type === "athlete").map(c => c.description)
  })).filter(a => a.title && /^https?:\/\//.test(a.link));
  return json({ items }, 200, 600);
}

// Every NFL game this week: teams, score, quarter/clock or kickoff time.
async function scoreboard() {
  const r = await fetch("https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard", { headers: UA });
  if (!r.ok) return json({ error: "NFL scoreboard unavailable (" + r.status + ")" }, 502, 0);
  const d = await r.json();
  const games = (d.events || []).map(e => {
    const c = (e.competitions || [])[0] || {};
    const side = k => (c.competitors || []).find(x => x.homeAway === k) || {};
    const st = (c.status || e.status || {}).type || {};
    return {
      away: (side("away").team || {}).abbreviation, home: (side("home").team || {}).abbreviation,
      awayScore: side("away").score || "0", homeScore: side("home").score || "0",
      state: st.state || "pre", detail: st.shortDetail || st.detail || ""
    };
  }).filter(g => g.away && g.home);
  return json({ games }, 200, 30);
}

// Season fantasy points for every player: [ppr, half, std, games played].
async function seasonStats(season) {
  const r = await fetch("https://api.sleeper.app/v1/stats/nfl/regular/" + season, { headers: UA });
  if (!r.ok) return json({ error: "Season stats unavailable (" + r.status + ")" }, 502, 0);
  const all = await r.json();
  const out = {};
  for (const id in all) {
    const s = all[id] || {};
    if (!s.pts_ppr && !s.pts_std) continue;
    out[id] = [s.pts_ppr || 0, s.pts_half_ppr || 0, s.pts_std || 0, s.gp || s.gms_active || 0];
  }
  return json(out, 200, 1800);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const p = url.pathname;
    try {
      if (p === "/" || p === "/index.html") {
        return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
      }
      const st = staticRoute(p);
      if (st) return st;
      if (p.startsWith("/api/push/")) return alertsRoute(request, env, p, url);
      if (p.startsWith("/api/sleeper/")) {
        const rest = p.slice("/api/sleeper/".length);
        if (!/^[A-Za-z0-9_\-\/.]+$/.test(rest)) return json({ error: "Bad path" }, 400, 0);
        const ttl = rest.startsWith("state/") ? 300 : rest.includes("/matchups/") ? 45 : rest.includes("trending") ? 900 : 120;
        const target = "https://api.sleeper.app/v1/" + rest + url.search;
        return cached(ctx, "s/" + rest + url.search, ttl, () => upstream(target, ttl));
      }
      if (p === "/api/players") return cached(ctx, "players-v1", 21600, slimPlayers);
      if (p.startsWith("/api/flea/")) {
        const ep = p.slice("/api/flea/".length);
        if (!FLEA_OK.has(ep)) return json({ error: "Unsupported Fleaflicker request" }, 400, 0);
        const ttl = ep === "FetchLeagueScoreboard" || ep === "FetchLeagueBoxscore" ? 45 : 180;
        const target = "https://www.fleaflicker.com/api/" + ep + url.search;
        return cached(ctx, "f/" + ep + url.search, ttl, () => upstream(target, ttl));
      }
      if (p === "/api/scoreboard") return cached(ctx, "scoreboard", 30, scoreboard);
      if (p === "/api/sstats") {
        const season = url.searchParams.get("season") || "";
        if (!/^\d{4}$/.test(season)) return json({ error: "Bad season" }, 400, 0);
        return cached(ctx, "sstats/" + season, 1800, () => seasonStats(season));
      }
      if (p === "/api/headlines") return cached(ctx, "headlines", 600, headlines);
      if (p === "/api/news") {
        const q = (url.searchParams.get("q") || "").slice(0, 80);
        if (!q) return json({ error: "Missing player name" }, 400, 0);
        return cached(ctx, "n/" + encodeURIComponent(q), 900, () => playerNews(q));
      }
      return new Response("Not found", { status: 404 });
    } catch (e) {
      return json({ error: "Something went wrong reaching the data source. Try again in a minute." }, 502, 0);
    }
  },
  async scheduled(event, env, ctx) {
    ctx.waitUntil(runMinute(env));
  }
};
